class Solution {
    private fun merge(first:String,second:String):String{
        if(second in first)return first;
        if(first in second)return second;
        for(overlap in minOf(first.length,second.length) downTo 0)if(first.regionMatches(first.length-overlap,second,0,overlap))return first+second.substring(overlap);
        return first+second
    };
    fun minimumString(a:String,b:String,c:String):String{
        val values=arrayOf(a,b,c);
        val orders=arrayOf(intArrayOf(0,1,2),intArrayOf(0,2,1),intArrayOf(1,0,2),intArrayOf(1,2,0),intArrayOf(2,0,1),intArrayOf(2,1,0));
        var best:String?=null;
        for(order in orders){
            val candidate=merge(merge(values[order[0]],values[order[1]]),values[order[2]]);
            if(best==null||candidate.length<best.length||candidate.length==best.length&&candidate<best)best=candidate
        };
        return best!!
    }
}

